parameters.jsonBody:
={{ {
  query: `query SMABestandPruefen($variantId: ID!) {
  currentAppInstallation {
    accessScopes {
      handle
    }
  }
  productVariant(id: $variantId) {
    id
    sku
    product {
      id
      title
    }
    inventoryItem {
      id
      tracked
      inventoryLevels(first: 20) {
        nodes {
          location {
            id
            name
            isActive
            fulfillsOnlineOrders
          }
          quantities(names: ["available", "on_hand", "committed"]) {
            name
            quantity
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  }
}`,
  variables: {
    variantId: $('SMA – Produkt – Shopify Sync – Marktzuordnung prüfen').first().json.externe_variant_id
  }
} }}

parameters.jsCode:
// Mode: Run Once for All Items; Language: JavaScript.
// Bereitet einen geprueften Bestandswert vor. Schreibt selbst keine Daten.
const fail = (message) => { throw new Error(`Bestandsabgleich: ${message}`); };
const single = (items, label) => {
  if (!Array.isArray(items) || items.length !== 1 || !items[0]?.json) {
    fail(`${label} muss genau einen Datensatz liefern.`);
  }
  return items[0].json;
};

const product = single(
  $('SMA – Produkt – Shopify Sync – Produkt prüfen').all(),
  'Produkt prüfen'
);
const mapping = single(
  $('SMA – Produkt – Shopify Sync – Marktzuordnung prüfen').all(),
  'Marktzuordnung prüfen'
);
const response = single($input.all(), 'Bestand abrufen');

if (!product.kunde_id || !product.produkt_id || !Number.isSafeInteger(product.id)) {
  fail('Kunden-, Produkt- oder Tabellenzeilen-ID fehlt.');
}

if (
  mapping.markt !== 'shopify' ||
  mapping.kunde_id !== product.kunde_id ||
  mapping.produkt_id !== product.produkt_id ||
  !mapping.markt_konto_id
) {
  fail('Marktzuordnung passt nicht zum Kunden und Produkt.');
}

if (
  response.errors !== undefined &&
  (!Array.isArray(response.errors) || response.errors.length > 0)
) {
  fail('Shopify hat einen GraphQL-Fehler geliefert.');
}

const variant = response.data?.productVariant;
if (
  !variant ||
  !variant.id ||
  variant.id !== mapping.externe_variant_id ||
  !variant.product?.id ||
  variant.product.id !== mapping.externe_produkt_id
) {
  fail('Shopify-Produkt oder Variante passt nicht zur Marktzuordnung.');
}

const inventory = variant.inventoryItem;
if (!inventory?.id || inventory.tracked !== true) {
  fail('Bestandsverfolgung ist nicht aktiv. Bestand wird nicht übernommen.');
}

const levels = inventory.inventoryLevels;
if (!Array.isArray(levels?.nodes) || levels.pageInfo?.hasNextPage !== false) {
  fail('Standortliste fehlt oder ist unvollständig.');
}

const seen = new Set();
const locations = [];

for (const level of levels.nodes) {
  const location = level?.location;
  if (
    !location?.id ||
    seen.has(location.id) ||
    typeof location.isActive !== 'boolean' ||
    typeof location.fulfillsOnlineOrders !== 'boolean'
  ) {
    fail('Standortdaten fehlen oder sind doppelt vorhanden.');
  }

  seen.add(location.id);
  if (!location.isActive || !location.fulfillsOnlineOrders) continue;

  const quantity = (name) => {
    const matches = Array.isArray(level.quantities)
      ? level.quantities.filter(q => q?.name === name)
      : [];

    if (matches.length !== 1 || !Number.isSafeInteger(matches[0].quantity)) {
      fail(`Ungültige oder fehlende Menge: ${name}.`);
    }
    return matches[0].quantity;
  };

  locations.push({
    location_id: location.id,
    name: location.name || '',
    available: quantity('available'),
    on_hand: quantity('on_hand'),
    committed: quantity('committed'),
  });
}

if (locations.length === 0) {
  fail('Kein aktiver Standort für Online-Bestellungen vorhanden.');
}

const sum = (field) => {
  const value = locations.reduce((total, location) => total + location[field], 0);
  if (!Number.isSafeInteger(value)) {
    fail('Bestandssumme liegt außerhalb des gültigen Zahlenbereichs.');
  }
  return value;
};

const available = sum('available');

return [{
  json: {
    kunde_id: product.kunde_id,
    produkt_id: product.produkt_id,
    n8n_produkt_zeile_id: product.id,
    markt: 'shopify',
    markt_konto_id: mapping.markt_konto_id,
    externe_produkt_id: variant.product.id,
    externe_variant_id: variant.id,
    inventory_item_id: inventory.id,
    tracked: true,
    bestand: Math.max(0, available),
    shopify_verfuegbar_roh: available,
    shopify_lagerbestand: sum('on_hand'),
    shopify_gebunden: sum('committed'),
    standorte: locations,
    ausgewertet_am: new Date().toISOString(),
  },
  pairedItem: { item: 0 },
}];

